import { reputationPoints, quests, schoolTeam, leaderboard } from './game.js';
import { verifiedHours, canManage, canReviewHour } from './domain.js';
const x = (v='') => String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c]);
const bar = (n,total,label) => `<div class="progress" role="progressbar" aria-label="${x(label)}" aria-valuemin="0" aria-valuemax="${total}" aria-valuenow="${Math.min(n,total)}"><span style="width:${Math.min(100,n/total*100)}%"></span></div>`;
const head = (eyebrow,title,copy) => `<div class="page-head"><div><span class="eyebrow">${x(eyebrow)}</span><h1>${x(title)}</h1><p>${x(copy)}</p></div></div>`;
const student = (s,id) => s.users.find(u=>u.id===id);
export function questCards(s,id,compact=false) {
  return `<div class="quest-list ${compact?'compact':''}">${quests(s,id).map((q,index)=>`<article class="quest ${q.complete?'earned':''}"><span class="quest-mark" aria-hidden="true">${q.complete?'✓':'◇'}</span><div class="quest-copy"><div class="quest-heading"><span class="quest-number">Quest ${String(index+1).padStart(2,'0')}</span><span class="quest-state">${q.complete?'Badge earned':'In progress'}</span></div><h3>${x(q.title)}</h3><p>${x(q.description)}</p><div class="quest-progress">${bar(q.current,q.target,q.title)}<small><strong>${Math.min(q.current,q.target)}</strong> / ${q.target}</small></div></div></article>`).join('')}</div>`;
}
export function teamCard(s,id) {
  const t=schoolTeam(s,id);
  return `<article class="card school-goal"><span class="eyebrow">BETTER TOGETHER</span><h2>${x(t.school)} team</h2><p>${x(t.start)} – ${x(t.end)} · ${t.members} participating ${t.members===1?'student':'students'}</p><div class="goal-number"><strong>${Number(t.hours).toFixed(2)}</strong><span>/ ${t.goal} verified hours</span></div>${bar(t.hours,t.goal,'School weekly service goal')}<p>${t.hours>=t.goal?'Weekly goal reached. Every contribution helped.':'A shared goal, built one shift at a time.'}</p>${t.optedIn?'<span class="tag">You’re on the team</span>':'<p>Your hours stay outside the team total until you join.</p>'}<a class="button button-link" href="#/profile">${t.optedIn?'Manage participation':'Join in profile settings'} →</a></article>`;
}
export function progressSnapshot(s,id) {
  return `<article class="card reputation-card"><span class="eyebrow">RELIABILITY & CONTRIBUTION</span><h2>Your reputation</h2><div class="goal-number"><strong>${reputationPoints(s,id)}</strong><span>earned points</span></div><p>Recognizes completed commitments, preparation, and confirmed contributions. Hours stay separate.</p><a href="#/progress">See your progress & point history →</a></article><article class="card"><div class="card-head"><h2>Your next achievements</h2><a href="#/progress">View all →</a></div>${questCards(s,id,true)}</article>${teamCard(s,id)}`;
}
export function weekCalendar(s) {
  const start=new Date(`${s.clock.slice(0,10)}T12:00:00`);
  const days=Array.from({length:7},(_,i)=>{const date=new Date(start);date.setDate(date.getDate()+i+1);return {date:`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`,label:date.toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric'})};});
  return `<article class="card week-card"><div class="card-head"><div><span class="eyebrow">MAKE ROOM FOR GOOD</span><h2>The next seven days</h2><p>Explore opportunities · these are not your bookings</p></div><a href="#/explore" class="button button-link">Find a shift →</a></div><div class="week-grid">${days.map(d=>{const events=s.events.filter(e=>e.status==='active'&&e.date===d.date&&e.shifts.some(sh=>`${e.date}T${sh.start}`>=s.clock));return `<div class="week-day"><time datetime="${d.date}">${x(d.label)}</time>${events.length?events.map(e=>`<a href="#/event/${e.id}"><strong>${x(e.title)}</strong><small>${e.shifts.filter(sh=>`${e.date}T${sh.start}`>=s.clock).reduce((n,sh)=>n+Math.max(0,sh.capacity-sh.filled),0)} spots · ${x(e.location)}</small></a>`).join(''):'<span class="week-empty">Room to explore</span>'}</div>`;}).join('')}</div></article>`;
}
export function rulesPanel() {
  return `<article class="card scoring-rules"><span class="eyebrow">CLEAR RULES. EARNED RECOGNITION.</span><h2>Two ways to see your service</h2><p><strong>Verified hours</strong> measure the amount of approved service. <strong>Reputation points</strong> accumulate evidence of reliable participation and contribution, so they also reflect how often you take part.</p><div class="point-rules"><div><strong>+10</strong><span>Verified completed shift</span></div><div><strong>+2</strong><span>Ready before the shift, awarded after completion</span></div><div><strong>+3</strong><span>Organizer confirms agreed tasks were fulfilled</span></div><div><strong>−5</strong><span>Admin-reviewed, unexcused missed shift</span></div></div><p>Up to 15 points per completed shift. Hours, email opens, logins, and reviews never generate points. Cancellations and excused absences carry no penalty. Quests award badges only. Your reputation never limits access to opportunities.</p><p>Points and badges update when records are corrected. Displayed reputation cannot fall below zero; all adjustments remain in your private history.</p></article>`;
}
export function progressView(s,id) {
  const u=student(s,id),hours=verifiedHours(s,id),ledger=(s.reputation||[]).filter(r=>r.studentId===id).slice().reverse();
  return `${head('YOUR SERVICE JOURNEY','Small commitments. Lasting progress.','Build a record of showing up, helping well, and learning along the way.')}<section class="game-metrics"><article class="card hours-card"><span class="eyebrow">QUANTITY</span><h2>Verified service</h2><div class="goal-number"><strong>${hours.toFixed(2)}</strong><span>/ ${u.requirementGoal} hours</span></div>${bar(hours,u.requirementGoal,'Verified hours goal')}<a href="#/hours">Review time cards →</a></article><article class="card reputation-card"><span class="eyebrow">RELIABILITY & CONTRIBUTION</span><h2>Reputation</h2><div class="goal-number"><strong>${reputationPoints(s,id)}</strong><span>earned points</span></div><p>Evidence of reliable actions, separate from time served.</p><a href="#/leaderboard">Optional school leaderboard →</a></article></section><section class="game-progress-layout"><article class="card"><h2>Your quests</h2><p>Earn badges at your own pace. No daily streaks to maintain.</p>${questCards(s,id)}</article>${teamCard(s,id)}</section><article class="card game-section"><h2>Private point history</h2><p>Each award and correction is recorded. Only your total and badges appear on an opted-in leaderboard.</p>${ledger.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Change</th><th>Reason</th><th>Shift</th><th>Recorded</th></tr></thead><tbody>${ledger.map(r=>{const reg=s.signups.find(v=>v.id===r.signupId),e=s.events.find(v=>v.id===reg?.eventId);return `<tr><td><strong>${Number(r.points??r.delta)>0?'+':''}${r.points??r.delta}</strong></td><td>${x(({completion:"Verified completion",readiness:"Advance readiness",tasks:"Confirmed contribution",absence:"Reviewed absence"})[r.reason]||r.reason)}${r.reversalOf?' · adjustment':''}</td><td>${x(e?.title||'Service record')}</td><td>${x((r.createdAt||r.at||r.time||'').replace('T',' '))}</td></tr>`;}).join('')}</tbody></table></div>`:'<p class="game-empty">Your next verified, completed shift can start your reputation story. Existing hours remain yours; past quality awards are not invented.</p>'}</article>${absencePanel(s,id)}${rulesPanel()}`;
}
export function leaderboardView(s,id) {
  const u=student(s,id),rows=leaderboard(s,id);
  return `${head('OPTIONAL RECOGNITION','Celebrate dependable contributions.',`${u.school} · lifetime reputation · tied scores share a rank`)}<div class="alert"><span>◇</span><div><strong>${u.leaderboardOptIn?'You have opted in':'Your profile is not on the leaderboard'}</strong><p>Only opted-in students with a scored, verified shift appear. Public entries use aliases, points, and earned badges. <a href="#/profile">Manage your alias and participation.</a></p></div></div><article class="card">${rows.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Rank</th><th>Volunteer alias</th><th>Reputation</th><th>Badges</th></tr></thead><tbody>${rows.map(r=>`<tr><td><span class="rank-token">${r.rank}</span></td><td><strong>${x(r.alias)}</strong>${r.studentId===id?' <span class="tag">You</span>':''}</td><td><strong>${r.points}</strong> points</td><td>${r.badges.map(b=>`<span class="tag">${x(typeof b==='string'?b:b.title)}</span>`).join(' ')||'Growing their story'}</td></tr>`).join('')}</tbody></table></div>`:'<div class="game-empty"><h2>A community worth showing up for.</h2><p>No qualifying entries yet. Complete a verified shift and opt in if you would like to share your progress.</p><a class="button button-primary" href="#/explore">Find an opportunity</a></div>'}</article>${teamCard(s,id)}`;
}
export function studentShiftTools(s,r,e) {
  if(!r||!['approved','attended'].includes(r.status))return '';
  const sh=e.shifts.find(v=>v.id===r.shiftId),ready=s.readiness?.some(v=>v.signupId===r.id),before=s.clock<`${e.date}T${sh.start}`;
  return `<div class="student-shift-tools">${r.status==='approved'&&before?`<button class="button button-light button-small" type="button" data-action="ready" data-signup="${r.id}" ${ready?'disabled':''}>${ready?'✓ Readiness confirmed':'I’ve reviewed the details and I’m ready'}</button><small>Preparation earns +2 after verified completion.</small>`:''}${r.status==='approved'&&!r.checkIn&&s.clock>=`${e.date}T${sh.start}`&&s.clock<`${e.date}T${sh.end}`?`<form class="code-entry" data-form="submit-code"><input type="hidden" name="signupId" value="${r.id}"><div class="field"><label for="code-${r.id}">Organizer’s six-digit code</label><input id="code-${r.id}" name="code" inputmode="numeric" pattern="[0-9]{6}" minlength="6" maxlength="6" autocomplete="off" required placeholder="000000"></div><button class="button button-primary" type="submit">Check in</button></form><small>Code entry records demo check-in only. Staff verify attendance and hours.</small>`:''}${r.checkIn?`<span class="tag">Checked in at ${x(r.checkIn)}</span>`:''}</div>`;
}
export function codePanel(s,e) {
  return `<article class="card game-section"><h2>Shift check-in codes</h2><p>Generate during the shift; a code lasts ten demo-clock minutes or until shift end. Sharing a code does not prove attendance. Checkout and hour verification remain separate.</p><div class="code-grid">${e.shifts.map(sh=>{const sessions=(s.codeSessions||[]).filter(c=>c.eventId===e.id&&c.shiftId===sh.id),c=sessions[sessions.length-1],active=c&&!c.revoked&&s.clock<c.expiresAt&&s.clock>=c.issuedAt;return `<section class="code-card"><h3>${x(sh.name)}</h3><p>${x(e.date)} · ${x(sh.start)}–${x(sh.end)}</p>${active?`<output class="attendance-code" aria-label="Current check-in code">${x(c.code)}</output><p>Expires ${x(c.expiresAt.replace('T',' '))}</p>`:'<p class="game-empty">No active code</p>'}<button type="button" class="button button-light" data-action="issue-code" data-event="${e.id}" data-shift="${sh.id}">${active?'Rotate code':'Generate code'}</button></section>`;}).join('')}</div></article>`;
}
export function assessmentPanel(s,eventId) {
  const records=s.hours.filter(h=>canReviewHour(s,h)&&(!eventId||h.eventId===eventId));
  return `<article class="card game-section"><h2>Completion & contribution review</h2><p>Verify hours first, then confirm reliable completion and agreed tasks. Corrections update the point ledger. No assessment is inferred from historical hours.</p>${records.length?records.map(h=>{const r=s.signups.find(r=>r.id===h.signupId),a=s.assessments?.find(v=>v.signupId===r?.id),u=student(s,h.studentId);return `<details class="assessment"><summary>${x(u?.name)} · ${x(h.title)} <span class="tag">${x(h.status)}</span></summary>${h.status==='verified'&&r?`<form data-form="assess-shift"><input type="hidden" name="signupId" value="${r.id}"><label class="check-card"><input type="checkbox" name="completed" ${a?.completed?'checked':''}><span>Shift completed as agreed<small>+10 after verification, plus any earned readiness reward</small></span></label><label class="check-card"><input type="checkbox" name="tasksCompleted" ${a?.tasksCompleted?'checked':''}><span>Agreed tasks fulfilled<small>+3 for organizer-confirmed contribution; requires completed shift</small></span></label><button class="button button-primary" type="submit">Save assessment</button></form>`:!r?'<p>Outside hours count toward service goals. They do not create shift reputation.</p>':'<p>Verify this time card before awarding reputation.</p>'}${h.status!=='pending'?`<form class="record-correction" data-form="correct-hour"><input type="hidden" name="hourId" value="${h.id}"><div class="field"><label for="correct-status-${h.id}">Correct record status</label><select id="correct-status-${h.id}" name="status"><option value="rejected">Rejected</option><option value="verified">Verified</option></select></div><div class="field"><label for="correct-reason-${h.id}">Reason for correction</label><input id="correct-reason-${h.id}" name="reason" required minlength="3" maxlength="500"></div><button class="button button-light" type="submit">Review correction</button></form>`:''}</details>`;}).join(''):'<p class="game-empty">Completed attendance will create time cards for review here.</p>'}</article>`;
}
export function absencePanel(s,id) {
  const actor=s.users.find(u=>u.id===s.activeUser[s.role]),items=(s.absences||[]).filter(a=>s.role==='student'?a.studentId===id:s.role==='admin'||canManage(s,s.events.find(e=>e.id===a.eventId)));
  return `<article class="card game-section"><h2>${s.role==='student'?'Attendance explanations':'Absence review queue'}</h2><p>A pending absence does not deduct points. Admins review explanations before finalizing an unexcused absence. Excused absences carry no penalty.</p>${items.length?items.map(a=>{const r=s.signups.find(r=>r.id===a.signupId),e=s.events.find(e=>e.id===(a.eventId||r?.eventId)),u=student(s,a.studentId);return `<details class="assessment"><summary>${x(s.role==='student'?e?.title:u?.name+' · '+e?.title)} <span class="tag">${x(a.status||a.outcome||'pending')}</span></summary>${a.explanation?`<p><strong>Student explanation:</strong> ${x(a.explanation)}</p>`:''}${a.reason?`<p><strong>Review:</strong> ${x(a.reason)}</p>`:''}${s.role==='student'?`<form data-form="absence-appeal"><input type="hidden" name="absenceId" value="${a.id}"><div class="field"><label for="appeal-${a.id}">Explain the absence or request a correction</label><textarea id="appeal-${a.id}" name="explanation" required minlength="3" maxlength="500">${x(a.explanation||'')}</textarea><small>No medical details are needed.</small></div><button class="button button-primary" type="submit">Send explanation</button></form>`:actor?.role==='admin'?`<form data-form="resolve-absence"><input type="hidden" name="absenceId" value="${a.id}"><div class="field"><label for="outcome-${a.id}">Review outcome</label><select id="outcome-${a.id}" name="outcome"><option value="excused">Excused · no penalty</option><option value="unexcused">Unexcused · −5 points</option></select></div><div class="field"><label for="reason-${a.id}">Review reason</label><textarea id="reason-${a.id}" name="reason" required minlength="3" maxlength="500"></textarea></div><button class="button button-primary" type="submit">Review decision</button></form>`:'<p>An administrator will review this case and any student explanation.</p>'}</details>`;}).join(''):'<p class="game-empty">No absence cases to review.</p>'}</article>`;
}
